"use client";

import React, { useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { motion } from "framer-motion";
import useSWR from "swr";
import DashboardLayout from "../../../components/dashboard/DashboardLayout";
import DashboardPageWrapper from "../../../components/dashboard/DashboardPageWrapper";
import { useAuth } from "@clerk/nextjs";

// Custom fetcher for SWR that handles errors properly
const fetcher = async (url) => {
  const response = await fetch(url, {
    credentials: 'include',
    headers: {
      'Accept': 'application/json'
    }
  });
  
  // Handle authentication errors
  if (response.status === 401) {
    window.location.href = '/sign-in?redirect=/dashboard/practices';
    throw new Error('Authentication required');
  }
  
  // Check if response is JSON
  const contentType = response.headers.get("content-type");
  if (!contentType || !contentType.includes("application/json")) {
    throw new Error("Server returned non-JSON response. Please reload the page.");
  }
  
  const data = await response.json();
  
  if (!response.ok) {
    throw new Error(data.error || "Failed to fetch practice data");
  }
  
  return data;
};

export default function PracticePage() {
  const { isLoaded } = useAuth();
  const params = useParams();
  const router = useRouter();
  const [activeTab, setActiveTab] = useState("transcript");
  
  // Fetch practice data when component mounts
  const { data: practice, error, isLoading } = useSWR(
    isLoaded && params.id ? `/api/practice-sessions/${params.id}` : null,
    fetcher,
    {
      revalidateOnFocus: false,
      dedupingInterval: 10000,
      errorRetryCount: 2
    }
  );
  
  // Helper function to safely get nested properties
  const safeGet = (obj, path, fallback) => {
    return path.split('.').reduce((acc, part) => 
      acc && acc[part] !== undefined ? acc[part] : fallback, obj);
  };
  
  // Helper function to format numbers
  const formatNumber = (num, decimals = 2) => {
    if (num === undefined || num === null) return 'N/A';
    return Number(num).toFixed(decimals);
  };
  
  // Go back to practices page
  const goBack = () => {
    router.push('/dashboard/practices');
  };
  
  return (
    <DashboardLayout>
      <DashboardPageWrapper 
        title={practice ? practice.title : "Practice Details"} 
        description={practice ? `Analyzed on ${practice.date} at ${practice.time}` : "Loading practice details..."}
        action={
          <motion.button
            onClick={goBack}
            className="px-4 py-2 bg-gray-800 text-white rounded-lg flex items-center space-x-2 hover:bg-gray-700 transition-colors"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
            </svg>
            <span>Back to Practices</span>
          </motion.button>
        }
      >
        {isLoading ? (
          <div className="flex justify-center items-center min-h-[400px]">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-purple-500"></div>
          </div>
        ) : error ? (
          <div className="bg-red-500/10 border border-red-500/30 rounded-xl p-6 text-center">
            <h3 className="text-xl font-medium text-red-400 mb-2">Error Loading Practice</h3>
            <p className="text-gray-400 mb-4">{error.message}</p>
            <div className="flex justify-center space-x-4">
              <button
                onClick={() => router.refresh()}
                className="px-4 py-2 bg-gray-800 text-white rounded-lg hover:bg-gray-700 transition-colors"
              >
                Retry
              </button>
              <button
                onClick={goBack}
                className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors"
              >
                Go Back
              </button>
            </div>
          </div>
        ) : practice ? (
          <div className="space-y-6">
            {/* Tabs */}
            <div className="flex border-b border-gray-800">
              <button
                className={`px-6 py-3 font-medium text-sm transition-colors ${
                  activeTab === "transcript"
                    ? "text-purple-500 border-b-2 border-purple-500"
                    : "text-gray-400 hover:text-gray-300"
                }`}
                onClick={() => setActiveTab("transcript")}
              >
                Transcript
              </button>
              <button
                className={`px-6 py-3 font-medium text-sm transition-colors ${
                  activeTab === "voice"
                    ? "text-blue-500 border-b-2 border-blue-500"
                    : "text-gray-400 hover:text-gray-300"
                }`}
                onClick={() => setActiveTab("voice")}
              >
                Voice Analysis
              </button>
              <button
                className={`px-6 py-3 font-medium text-sm transition-colors ${
                  activeTab === "text"
                    ? "text-green-500 border-b-2 border-green-500"
                    : "text-gray-400 hover:text-gray-300"
                }`}
                onClick={() => setActiveTab("text")}
              >
                Text Analysis
              </button>
              <button
                className={`px-6 py-3 font-medium text-sm transition-colors ${
                  activeTab === "recommendations"
                    ? "text-yellow-500 border-b-2 border-yellow-500"
                    : "text-gray-400 hover:text-gray-300"
                }`}
                onClick={() => setActiveTab("recommendations")}
              >
                Recommendations
              </button>
            </div>
            
            {/* Tab Content */}
            <div className="bg-gray-900/50 backdrop-blur-sm rounded-xl p-6 border border-gray-800">
              {activeTab === "transcript" && (
                <div>
                  <h3 className="text-xl font-medium text-gray-200 mb-4">Transcript</h3>
                  {practice.transcription ? (
                    <div className="bg-gray-800/50 rounded-lg p-4 whitespace-pre-wrap text-gray-300">
                      {practice.transcription}
                    </div>
                  ) : (
                    <div className="text-center text-gray-400 py-8">
                      No transcript available for this practice session.
                    </div>
                  )}
                </div>
              )}
              
              {/* Other tab contents will be implemented similarly */}
            </div>
          </div>
        ) : (
          <div className="text-center text-gray-400 py-8">
            Practice not found or you don't have permission to view it.
          </div>
        )}
      </DashboardPageWrapper>
    </DashboardLayout>
  );
}
